export type CcnpCase = {
  domain: string;
  title: string;
  rootCause: string;
  change: string;
  complaint: string;
  evidence: string;
  fix: string;
};

const c = (domain: string, rows: Omit<CcnpCase, "domain">[]): CcnpCase[] => rows.map((row) => ({ domain, ...row }));

